import axios from 'axios';
import SpotifyWebApi from 'spotify-web-api-js';

const spotifyApi = new SpotifyWebApi();
const API_URL = 'http://localhost:3001/api'; // Backend API URL

// Set access token for Spotify API client
export const setAccessToken = (token) => {
  spotifyApi.setAccessToken(token);
};

// Function to exchange the authorization code for an access token
export const exchangeToken = async (code) => {
  try {
    const response = await axios.post(`${API_URL}/exchange-token`, { code });
    const { access_token } = response.data;
    setAccessToken(access_token);
    return access_token;
  } catch (error) {
    console.error('Error exchanging code for token:', error);
    throw error;
  }
};

// Function to validate the token
export const validateToken = async () => {
  try {
    await spotifyApi.getMe(); // Test if the token is valid
    return true;
  } catch (error) {
    console.error('Token validation failed:', error);
    return false;
  }
};

// Search tracks by query
export const searchTracks = async (query) => {
  try {
    const response = await spotifyApi.searchTracks(query, { limit: 8 });
    return response.tracks.items;
  } catch (error) {
    console.error('Error fetching tracks:', error);
    return [];
  }
};

// Get user's top artists using the backend
export const getTopArtists = async () => {
  try {
    const response = await axios.get(`${API_URL}/top-artists`, {
      headers: {
        Authorization: `Bearer ${spotifyApi.getAccessToken()}`, // Include the access token in headers
      },
    });
    return response.data;
  } catch (error) {
    if (error.response && error.response.status === 401) {
      alert('Your session expired or lacks necessary permissions. Please re-login.');
    }
    console.error('Error fetching top artists:', error);
    return [];
  }
};

// Get new releases for given artist IDs using the backend
export const getNewReleases = async (artistIds) => {
  try {
    const response = await axios.post(
      `${API_URL}/new-releases`,
      { artistIds },
      {
        headers: {
          Authorization: `Bearer ${spotifyApi.getAccessToken()}`, // Include the access token in headers
        },
      }
    );
    return response.data; // Expecting flattened album list from backend
  } catch (error) {
    console.error('Error fetching new releases:', error);
    return [];
  }
};

// Get audio analysis of a track
export const getAudioAnalysis = async (trackId) => {
  try {
    const response = await spotifyApi.getAudioAnalysisForTrack(trackId);
    return response;
  } catch (error) {
    console.error('Error fetching audio analysis:', error);
    return null;
  }
};
